from pathlib import Path
import json,html
p=Path('/tmp/session14-mockups/campaigns');r=json.loads((p/'record-receipt.json').read_text());esc=html.escape
rows=''.join(f'<div class="election"><h3>{esc(o["title"].replace("Seat in the ",""))}</h3><p>{esc(o["timing"])}</p><small>{esc(o["provider"])}</small></div>' for o in r['offices'])
css='''@font-face{font-family:F;src:url(fira-sans-400.ttf)}@font-face{font-family:C;src:url(cinzel-800.ttf)}*{box-sizing:border-box}body{margin:0;width:1920px;height:1080px;background:url(room-art.jpg) center/cover;font:18px/1.45 F;color:#f2ede4;overflow:hidden}.panel{position:absolute;left:365px;top:180px;width:1190px;padding:44px 48px 40px;background:rgba(24,24,25,.86);backdrop-filter:blur(3px);border:2px solid #c4a55e;border-radius:9px;box-shadow:0 0 0 1px #171717,inset 0 0 0 1px #d3ae6380}.corner{position:absolute;width:32px;height:32px;background-image:url(sheet.png);background-size:973.2px 581.4px}.tl{top:0;left:0;background-position:-33px -29.4px}.tr{top:0;right:0;background-position:-906px -29.4px}.bl{bottom:0;left:0;background-position:-33px -513px}.br{bottom:0;right:0;background-position:-906px -513px}h1{font:32px C;color:#e7d3a7;margin:0 0 10px}header p{margin:0;color:#d3c6b0}.columns{display:grid;grid-template-columns:1.3fr 1fr 1fr;gap:42px;margin-top:38px}h2{font:22px C;color:#d6bd84;margin:0 0 22px}h3{font:18px F;margin:0 0 4px}p{margin:0 0 12px}.election{margin:0 0 21px}small{font:15px F;color:#b8b3aa}.quiet{color:#d4cec1}footer{margin-top:25px;font:15px F;color:#b8b3aa}.x{position:absolute;right:25px;top:20px;font:25px F;background:none;border:0;color:#dfdcd4;padding:0}.note{position:absolute;top:24px;right:24px;background:#171919bc;padding:9px 13px;font:14px F}.return{display:inline-block;vertical-align:middle;width:24px;height:24px;margin-right:16px;background:url(sheet.png) -402.8px -314px/648.8px 387.6px}'''
content=f'''<aside class="note">Session 14 · Campaigns review candidate · saved opening records + released art · not implemented</aside><main class="panel"><i class="corner tl"></i><i class="corner tr"></i><i class="corner bl"></i><i class="corner br"></i><button class="x" aria-label="Close">×</button><header><h1><span class="return" aria-label="Back"></span>Campaigns</h1><p>{esc(r['campaign']['candidateName'])} · {esc(r['place']['displayName'])}</p></header><section class="columns"><section><h2>Elections here</h2>{rows}</section><section><h2>People met</h2><p class="quiet">No campaigning contacts are recorded yet.</p><small>Contacts appear here after you meet people while campaigning.</small></section><section><h2>Your campaign</h2><p>No campaign is filed.</p><p class="quiet">No field reading is recorded.</p></section></section><footer>Dates above are the game's current calendar records. Some local filing requirements have not been recorded.</footer></main>'''
(p/'campaigns.html').write_text(f'<!doctype html><html><head><meta charset="utf-8"><style>{css}</style></head><body>{content}</body></html>')
